style.css:
@-moz-document domain("roblox.com") {
/* Panele */
    .rbx-left-col,
    .content,
    .section,
    .card {
        background: rgba(54, 48, 46, 0.80) !important;
    }

    /* Górny pasek */
    #header {
        background: rgba(54, 48, 46, 0.90) !important;
    }

    /* Przyciski */
    button,
    .btn-common-md,
    .btn-control-md {
        background: rgba(54, 48, 46, 0.85) !important;
        border-color: rgba(54, 48, 46, 1) !important;
    }

    /* PLAY */
    .btn-primary-md,
    .btn-primary-lg {
        background: rgba(54, 48, 46, 0.95) !important;
        border-color: rgba(54, 48, 46, 1) !important;
    }

    /* Hover */
    button:hover,
    .btn-common-md:hover,
    .btn-control-md:hover,
    .btn-primary-md:hover,
    .btn-primary-lg:hover {
        background: rgba(54, 48, 46, 1) !important;
    }

    /* About / Store / Servers */
    .rbx-tab {
        background: rgba(54, 48, 46, 0.70) !important;
    }

    /* Karty */
    .game-card,
    .event-card {
        background: rgba(54, 48, 46, 0.75) !important;
    }
}
